       AND NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = to_regclass('website.visitor_tracks') AND conname = 'ck_visitor_tracks_url_max_length__max_length') THEN
        IF EXISTS (SELECT 1 FROM website.visitor_tracks WHERE NOT ((char_length(url) <= 500))) THEN
            RAISE NOTICE 'ck_visitor_tracks_url_max_length__max_length not added: stored rows of website.visitor_tracks break it';
        ELSE
            ALTER TABLE website.visitor_tracks ADD CONSTRAINT ck_visitor_tracks_url_max_length__max_length CHECK ((char_length(url) <= 500));
        END IF;
    END IF;
EXCEPTION WHEN undefined_column THEN
    RAISE NOTICE 'ck_visitor_tracks_url_max_length__max_length not added: website.visitor_tracks lacks a column it reads';
END $$;

